/* Iridium-NG: kernels with loops, break/continue, local arrays, threadgroup memory + barriers, atomics, structs with
 * float3/uchar/ushort/half and a global constant table. The metallib (ng.metallib) is modern AIR with opaque pointers,
 * generated by tests/metal/air/mkmetallib.py. Also SIMD-group operations and bfloat. Every result is compared with the
 * CPU. Prints "METAL IRIDIUM-NG OK". */
#import <Foundation/Foundation.h>
#import <Metal/Metal.h>
#include <math.h>

typedef struct { float p[4]; uint8_t tag; uint8_t pad; uint16_t id; uint16_t h; uint16_t pad2; float w; float pad3; } Item; /* = kernel's Item (32 bytes) */

static float h2f(uint16_t h) {
    uint32_t s = h >> 15, e = (h >> 10) & 31, f = h & 1023;
    if (!e) return (s ? -1 : 1) * ldexpf((float)f, -24);
    return (s ? -1 : 1) * ldexpf((float)(f | 1024), (int)e - 25);
}
static uint16_t f2h(float x) { /* exact for the values used here */
    if (x == 0) return 0;
    int e; float m = frexpf(fabsf(x), &e);
    return (uint16_t)((x < 0) << 15 | (uint16_t)(e + 14) << 10 | ((uint16_t)(m * 2048) & 1023));
}

static uint16_t bf16(float f) { uint32_t u; memcpy(&u, &f, 4); u += 0x7FFF + ((u >> 16) & 1); return (uint16_t)(u >> 16); }
static float bf2f(uint16_t b) { uint32_t u = (uint32_t)b << 16; float f; memcpy(&f, &u, 4); return f; }
static int fails;
#define CHECK(cond, ...) do { if (!(cond)) { if (fails++ < 8) printf("FAIL " __VA_ARGS__); } } while (0)

static void CHECK_MMA(const float *A, const float *B, const float *out, const float *e) {
    for (int r = 0; r < 8; r++)
        for (int c = 0; c < 8; c++) {
            float d = 1;
            for (int k = 0; k < 8; k++) d += A[r * 8 + k] * B[k * 8 + c];
            CHECK(out[r * 8 + c] == d, "mma D[%d][%d] = %f, expected %f\n", r, c, out[r * 8 + c], d);
            CHECK(out[64 + c * 8 + r] == A[r * 8 + c], "mma store transposed [%d][%d] = %f, expected %f\n", c, r, out[64 + c * 8 + r], A[r * 8 + c]);
            CHECK(out[128 + (8 + r) * 16 + 8 + c] == d - 1, "mma store with origin [%d][%d] = %f, expected %f\n", r, c, out[128 + (8 + r) * 16 + 8 + c], d - 1);
            CHECK(out[128 + r * 16 + c] == 0, "mma store with origin wrote outside [%d][%d]\n", r, c);
        }
    for (int l = 0; l < 32; l++) { /* thread_elements(): lane l owns (row, col) and (row, col+1) */
        int row = ((l >> 4) & 1) * 4 + ((l >> 2) & 1) * 2 + ((l >> 1) & 1), col = ((l >> 3) & 1) * 4 + (l & 1) * 2;
        CHECK(e[2 * l] == A[row * 8 + col] && e[2 * l + 1] == A[row * 8 + col + 1], "mma thread_elements lane %d = %f %f\n", l, e[2 * l], e[2 * l + 1]);
    }
}
static void CHECK_SIMD(const float *in, const float *out, const uint32_t *info, const uint16_t *bf) {
    const int N = 256;
    for (int g = 0; g < N; g++) {
        uint32_t L = info[2 * g], sz = info[2 * g + 1];
        CHECK(sz >= 1 && sz <= 128 && L == (uint32_t)g % sz, "simd lane %u / size %u on thread %d\n", L, sz, g);
        if (!(sz >= 1 && sz <= 128 && L == (uint32_t)g % sz)) return;
        int base = g - (int)L;
        float sum = 0, pre = 0, mx = -1e30f; int isum = 0; int any = 0;
        for (int i = 0; i < (int)sz; i++) {
            float v = in[base + i];
            sum += v; isum += (int)v; if (v > mx) mx = v; if (v > 5.5f) any = 1;
            if (base + i < g) pre += v;
        }
        CHECK(out[g * 4] == sum, "simd_sum[%d] = %f, expected %f\n", g, out[g * 4], sum);
        CHECK(out[g * 4 + 1] == pre, "simd_prefix_exclusive_sum[%d] = %f, expected %f\n", g, out[g * 4 + 1], pre);
        if (L + 1 < sz) CHECK(out[g * 4 + 2] == in[g + 1], "simd_shuffle_down[%d] = %f, expected %f\n", g, out[g * 4 + 2], in[g + 1]);
        float w = mx + (float)isum + (any ? 1000.0f : 0.0f);
        CHECK(out[g * 4 + 3] == w, "simd_max/sum_i/any[%d] = %f, expected %f\n", g, out[g * 4 + 3], w);
        uint16_t b = bf16(bf2f(bf16(in[g] * 3.3f + 0.1f)) * 1.5f);
        CHECK(abs((int)bf[g] - (int)b) <= 1, "bfloat[%d] = %04x, expected %04x\n", g, bf[g], b);
    }
}

static id<MTLComputePipelineState> pso(id<MTLDevice> d, id<MTLLibrary> l, NSString *n) {
    NSError *e = nil;
    id<MTLFunction> f = [l newFunctionWithName:n];
    if (!f) { printf("METAL: missing function %s\n", n.UTF8String); exit(1); }
    id<MTLComputePipelineState> p = [d newComputePipelineStateWithFunction:f error:&e];
    if (!p) { printf("METAL: %s: %s\n", n.UTF8String, e.localizedDescription.UTF8String); exit(1); }
    return p;
}
static void run(id<MTLCommandQueue> q, id<MTLComputePipelineState> p, NSArray *bufs, NSUInteger groups, NSUInteger perGroup) {
    id<MTLCommandBuffer> cb = [q commandBuffer];
    id<MTLComputeCommandEncoder> e = [cb computeCommandEncoder];
    [e setComputePipelineState:p];
    for (NSUInteger i = 0; i < bufs.count; i++) [e setBuffer:bufs[i] offset:0 atIndex:i];
    [e dispatchThreadgroups:MTLSizeMake(groups, 1, 1) threadsPerThreadgroup:MTLSizeMake(perGroup, 1, 1)];
    [e endEncoding];
    [cb commit];
    [cb waitUntilCompleted];
}

int main(int argc, char **argv) {
    @autoreleasepool {
        id<MTLDevice> dev = MTLCreateSystemDefaultDevice();
        NSString *dir = [[NSString stringWithUTF8String:argv[0]] stringByDeletingLastPathComponent];
        NSError *err = nil;
        id<MTLLibrary> lib = [dev newLibraryWithFile:[dir stringByAppendingPathComponent:@"ng.metallib"] error:&err];
        if (!lib) { printf("METAL: %s\n", err.localizedDescription.UTF8String); return 1; }
        id<MTLCommandQueue> q = [dev newCommandQueue];
        const int N = 256;

        /* ---- loops */
        id<MTLBuffer> in = [dev newBufferWithLength:N * 4 options:0], out = [dev newBufferWithLength:N * 4 options:0], iout = [dev newBufferWithLength:N * 8 options:0];
        float *pin = in.contents;
        for (int i = 0; i < N; i++) pin[i] = (float)((i * 37) % 101) / 10.0f - 3.0f;
        run(q, pso(dev, lib, @"loops"), @[in, out, iout], N / 64, 64);
        float *po = out.contents; int *pio = iout.contents;
        for (unsigned g = 0; g < (unsigned)N; g++) {
            float acc = 0;
            for (int i = 0; i < 64; i++) {
                if (i % 7 == 3) continue;
                if (acc > 1000.0f) break;
                acc += pin[(g + i) % 256] * (float)(i & 3);
            }
            int lut[8];
            for (int i = 0; i < 8; i++) lut[i] = (int)(g * 3 + i) ^ (i << 2);
            int k = lut[g & 7] / 3 - (int)(g % 5);
            int n = 0, x = (int)g + 1;
            while (x != 1 && n < 200) { x = (x & 1) ? 3 * x + 1 : x >> 1; n++; }
            float c = pin[g] < -1 ? -1 : pin[g] > 1 ? 1 : pin[g];
            float want = acc + sinf((float)g * 0.01f) * sqrtf((float)g) + powf(2.0f, (float)(g & 7)) + c;
            int wi = (k < 1000 ? k : 1000) + (int)(g > 3 ? g : 3);
            CHECK(fabsf(po[g] - want) <= 1e-3f * fmaxf(1, fabsf(want)), "loops out[%u] = %f, expected %f\n", g, po[g], want);
            CHECK(pio[2 * g] == wi, "loops iout[%u] = %d, expected %d\n", g, pio[2 * g], wi);
            CHECK(pio[2 * g + 1] == n, "loops collatz[%u] = %d, expected %d\n", g, pio[2 * g + 1], n);
        }
        printf("loops: %s\n", fails ? "FAIL" : "ok");
        int f0 = fails;

        /* ---- reduce: 4 groups x 256 threads */
        const int G = 4;
        id<MTLBuffer> rin = [dev newBufferWithLength:G * 256 * 4 options:0], sums = [dev newBufferWithLength:G * 4 options:0], total = [dev newBufferWithLength:4 options:0];
        uint32_t *pr = rin.contents, want = 0;
        for (int i = 0; i < G * 256; i++) { pr[i] = (uint32_t)(i * 7 + 1); want += pr[i]; }
        run(q, pso(dev, lib, @"reduce"), @[rin, sums, total], G, 256);
        uint32_t *ps = sums.contents;
        for (int g = 0; g < G; g++) {
            uint32_t s = 0;
            for (int i = 0; i < 256; i++) s += pr[g * 256 + i];
            CHECK(ps[g] == s + 765, "reduce sums[%d] = %u, expected %u\n", g, ps[g], s + 765);
        }
        CHECK(*(uint32_t *)total.contents == want, "reduce total = %u, expected %u\n", *(uint32_t *)total.contents, want);
        printf("reduce (threadgroup + barriers + atomic): %s\n", fails > f0 ? "FAIL" : "ok");
        f0 = fails;

        /* ---- structs */
        id<MTLBuffer> items = [dev newBufferWithLength:N * sizeof(Item) options:0], o4 = [dev newBufferWithLength:N * 16 options:0];
        Item *it = items.contents, orig[256];
        for (int g = 0; g < N; g++) {
            it[g] = (Item){{g * 0.5f, 1.0f + g, -g * 0.25f, 0}, (uint8_t)(g % 200), 0, (uint16_t)(g * 7), f2h((float)(g % 16) + 0.5f), 0, 1.5f, 0};
            orig[g] = it[g];
        }
        run(q, pso(dev, lib, @"structs"), @[items, o4], N / 64, 64);
        const float table[4] = {1.5f, -2.0f, 0.25f, 8.0f};
        float *pv = o4.contents;
        for (int g = 0; g < N; g++) {
            Item a = orig[g];
            float s = a.p[0] * a.p[0] + a.p[1] * a.p[1] + a.p[2] * a.p[2] + a.tag + a.id + h2f(a.h) + a.w * table[g & 3];
            CHECK(fabsf(pv[g * 4] - s) <= 1e-3f * fmaxf(1, fabsf(s)), "structs s[%d] = %f, expected %f\n", g, pv[g * 4], s);
            CHECK(pv[g * 4 + 1] == a.p[1] && pv[g * 4 + 2] == (float)g && pv[g * 4 + 3] == table[(g + 1) & 3], "structs out[%d] = %f %f %f\n", g, pv[g * 4 + 1], pv[g * 4 + 2], pv[g * 4 + 3]);
            CHECK(it[g].tag == (uint8_t)(a.tag + 1) && it[g].id == (uint16_t)(a.id * 2) && h2f(it[g].h) == h2f(a.h) * 0.5f && it[g].w == a.w && it[g].p[0] == a.p[0],
                  "structs item[%d]: tag %u id %u h %f\n", g, it[g].tag, it[g].id, h2f(it[g].h));
        }
        printf("structs (float3, uchar, ushort, half, constant table): %s\n", fails > f0 ? "FAIL" : "ok");

        /* ---- simdk: SIMD-group ops + bfloat */
        f0 = fails;
        id<MTLBuffer> sin_ = [dev newBufferWithLength:N * 4 options:0], sout = [dev newBufferWithLength:N * 16 options:0],
                      sinfo = [dev newBufferWithLength:N * 8 options:0], sbf = [dev newBufferWithLength:N * 2 options:0];
        float *si = sin_.contents;
        for (int g = 0; g < N; g++) si[g] = (float)((g * 7) % 13 - 6);
        run(q, pso(dev, lib, @"simdk"), @[sin_, sout, sinfo, sbf], N / 64, 64);
        CHECK_SIMD(si, (float *)sout.contents, (uint32_t *)sinfo.contents, (uint16_t *)sbf.contents);
        printf("simd (sum, prefix, shuffle_down, max, any) + bfloat: %s (SIMD group of %u)\n", fails > f0 ? "FAIL" : "ok", ((uint32_t *)sinfo.contents)[1]);

        /* ---- function constants: the same kernel specialized twice */
        f0 = fails;
        for (int pass = 0; pass < 2; pass++) {
            MTLFunctionConstantValues *cv = [MTLFunctionConstantValues new];
            uint32_t mode = pass ? 0 : 2; float scale = pass ? 2.0f : 0.5f;
            if (pass) [cv setConstantValue:&mode type:MTLDataTypeUInt withName:@"mode"]; /* by name and by index */
            else [cv setConstantValue:&mode type:MTLDataTypeUInt atIndex:0];
            [cv setConstantValue:&scale type:MTLDataTypeFloat atIndex:3];
            NSError *e = nil;
            id<MTLFunction> fn = [lib newFunctionWithName:@"fck" constantValues:cv error:&e];
            id<MTLComputePipelineState> p = [dev newComputePipelineStateWithFunction:fn error:&e];
            id<MTLBuffer> fo = [dev newBufferWithLength:64 * 4 options:0];
            run(q, p, @[fo], 1, 64);
            float *pf = fo.contents;
            for (int g = 0; g < 64; g++) {
                float want = (mode == 2 ? 100.0f : 0.0f) + g * scale;
                CHECK(pf[g] == want, "function constant (pass %d) out[%d] = %f, expected %f\n", pass, g, pf[g], want);
            }
            if (pass == 0) CHECK(fn.functionConstantsDictionary.count == 2, "functionConstantsDictionary: %lu\n", (unsigned long)fn.functionConstantsDictionary.count);
        }
        printf("function constants (by index and by name): %s\n", fails > f0 ? "FAIL" : "ok");

        /* ---- simdgroup_matrix (needs 32-wide SIMD groups, like Apple GPUs) */
        if (((uint32_t *)sinfo.contents)[1] == 32) {
            f0 = fails;
            id<MTLBuffer> ma = [dev newBufferWithLength:256 options:0], mb = [dev newBufferWithLength:256 options:0],
                          mo = [dev newBufferWithLength:384 * 4 options:0], me = [dev newBufferWithLength:256 options:0];
            float *pa = ma.contents, *pb = mb.contents;
            for (int i = 0; i < 64; i++) { pa[i] = (float)(i % 7) - 3; pb[i] = (float)((i * 5) % 9) * 0.5f; }
            run(q, pso(dev, lib, @"mma"), @[ma, mb, mo, me], 1, 32);
            CHECK_MMA(pa, pb, mo.contents, me.contents);
            printf("simdgroup_matrix (load, store, transpose, origin, multiply_accumulate): %s\n", fails > f0 ? "FAIL" : "ok");
        } else printf("simdgroup_matrix: skipped (the GPU uses SIMD groups of %u, not 32)\n", ((uint32_t *)sinfo.contents)[1]);
        printf(fails ? "METAL IRIDIUM-NG FAIL\n" : "METAL IRIDIUM-NG OK\n");
        return fails != 0;
    }
}
